changes.sections/multicolumn-features-2.liquid:
{% # theme-check-disable %}
<div class="multicolumn-features multicolumn-features--{{ section.settings.text_alignment }}" style="--columns: {{ section.settings.columns_desktop }};">
  {%- if section.settings.title != blank -%}
    <h2 class="multicolumn-features__title">{{ section.settings.title | escape }}</h2>
  {%- endif -%}
  <ul class="multicolumn-features__list">
    {%- for block in section.blocks -%}
      <li class="multicolumn-features__item" {{ block.shopify_attributes }}>
        <span class="icon icon--{{ block.settings.icon }}"></span>
        <h3>{{ block.settings.heading | escape }}</h3>
        <div class="rte">{{ block.settings.text }}</div>
      </li>
    {%- endfor -%}
  </ul>
</div>

{% schema %}
{
  "name": "Multicolumn features",
  "tag": "section",
  "class": "multicolumn-features",
  "settings": [
    {"type": "text", "id": "title", "label": "Title", "default": "Why shop with us"},
    {"type": "range", "id": "columns_desktop", "label": "Columns on desktop", "min": 1, "max": 4, "step": 1, "default": 3},
    {"type": "select", "id": "text_alignment", "label": "Text alignment", "options": [{"value": "left", "label": "Left"}, {"value": "center", "label": "Center"}], "default": "center"}
  ],
  "blocks": [
    {
      "type": "column",
      "name": "Column",
      "settings": [
        {"type": "text", "id": "heading", "label": "Heading", "default": "Feature"},
        {"type": "richtext", "id": "text", "label": "Text"},
        {"type": "select", "id": "icon", "label": "Icon", "options": [{"value": "truck", "label": "Truck"}, {"value": "gift", "label": "Gift"}, {"value": "lock", "label": "Lock"}], "default": "truck"}
      ]
    }
  ],
  "max_blocks": 6,
  "presets": [
    {"name": "Multicolumn features", "blocks": [{"type": "column"}, {"type": "column"}, {"type": "column"}]}
  ]
}
{% endschema %}
